S = {'cc': 'SK', 'fam': 'Social', 'doc': '# SK 2025: employer social contributions (2200) and payroll taxes (3000)\n\nSource: Slov-Lex (official), versions effective 2025-01-01: zákon 461/2003 Z. z. o sociálnom poistení (`sk/law/z461_2003_20250101.html`), zákon 580/2004 Z. z. o zdravotnom poistení (`sk/law/z580_2004_20250101.html`).\n* § 130: "Sadzba poistného na nemocenské poistenie je pre ... b) zamestnávateľa 1,4 % z vymeriavacieho základu"; § 131 (1): "b) zamestnávateľa za zamestnanca 14 %"; § 132: "b) zamestnávateľa 3 %"\n* § 133: "Sadzba poistného na úrazové poistenie pre zamestnávateľa je 0,8 %"; § 135: garančné "0,25 %"; § 136 b) 1.: zamestnávateľ, ktorý platí poistné na financovanie podpory, "0,5 %"; § 136a: "0,5 %"; § 137 a): "zamestnávateľa 4,75 %"\n* zákon 580/2004 § 12 (1): "d) zamestnávateľa 10 % z vymeriavacieho základu"\n', 'lean': 'def c0 : Contribution := { name := "Nemocenské poistenie (zamestnávateľ)", sched := Schedule.flat 140, ceiling := -1 }\ndef c1 : Contribution := { name := "Starobné poistenie (zamestnávateľ)", sched := Schedule.flat 1400, ceiling := -1 }\ndef c2 : Contribution := { name := "Invalidné poistenie (zamestnávateľ)", sched := Schedule.flat 300, ceiling := -1 }\ndef c3 : Contribution := { name := "Úrazové poistenie", sched := Schedule.flat 80, ceiling := -1 }\ndef c4 : Contribution := { name := "Garančné poistenie", sched := Schedule.flat 25, ceiling := -1 }\ndef c5 : Contribution := { name := "Poistenie v nezamestnanosti (zamestnávateľ)", sched := Schedule.flat 50, ceiling := -1 }\ndef c6 : Contribution := { name := "Poistné na financovanie podpory", sched := Schedule.flat 50, ceiling := -1 }\ndef c7 : Contribution := { name := "Rezervný fond solidarity (zamestnávateľ)", sched := Schedule.flat 475, ceiling := -1 }\ndef c8 : Contribution := { name := "Zdravotné poistenie (zamestnávateľ)", sched := Schedule.flat 1000, ceiling := -1 }\n\ndef contribs : List (Contribution × Oecd × String) :=\n  [(c0, .sscEmployer, "zákon 461/2003 Z. z. § 130 písm. b): 1,4 %"),\n   (c1, .sscEmployer, "zákon 461/2003 Z. z. § 131 ods. 1 písm. b): 14 %"),\n   (c2, .sscEmployer, "zákon 461/2003 Z. z. § 132 písm. b): 3 %"),\n   (c3, .sscEmployer, "zákon 461/2003 Z. z. § 133: 0,8 %"),\n   (c4, .sscEmployer, "zákon 461/2003 Z. z. § 135: 0,25 %"),\n   (c5, .sscEmployer, "zákon 461/2003 Z. z. § 136 písm. b) bod 1: 0,5 %"),\n   (c6, .sscEmployer, "zákon 461/2003 Z. z. § 136a: 0,5 %"),\n   (c7, .sscEmployer, "zákon 461/2003 Z. z. § 137 písm. a): 4,75 %"),\n   (c8, .sscEmployer, "zákon 580/2004 Z. z. § 12 ods. 1 písm. d): 10 %")]\n\n/-- On the household\'s wages: each adult, each contribution (borne by the employer). -/\ndef householdCharges (g : CanonGlobal) : List Charge :=\n  if g.entity == .company then [] else\n  (g.household.adults.zipIdx.filter (fun (a, _) => 0 < a.wages)).flatMap fun (a, i) =>\n    contribs.map fun (c, o, st) =>\n      charge o c.name a.wages id (fun x => c.amount x) (event := s!"adult {i + 1}") (level := .social)\n        (bearer := .employer) (statute := st)\n\n/-- On a company\'s payroll, spread evenly over its employees (ceilings per employee). -/\ndef companyCharges (g : CanonGlobal) : List Charge :=\n  if g.entity != .company || g.company.payroll ≤ 0 then [] else\n  let n : Int := max 1 (g.company.employees : Int)\n  let avg := g.company.payroll / n\n  contribs.map fun (c, o, st) =>\n    charge o c.name g.company.payroll id (fun _ => n * c.amount avg) (event := "payroll") (level := .social)\n      (statute := st)\n', 'families': [('2200/3000 employer contributions', ['.sscEmployer'], 'householdCharges g ++ companyCharges g')], 'notes': ['SK 2200/3000: Slov-Lex znenie účinné od 1.1.2025'], 'unsupported': [('g.household.adults.any (fun a => 150000 < a.wages)', 'maximum assessment base for social insurance (§ 138: a multiple of the všeobecný vymeriavací základ, the 2023 figure not read) not applied; úrazové and health have none'), ('g.household.adults.any (fun a => 0 < a.wages)', 'reduced health rate for employees with disabilities (5 %) not modelled'), ('g.entity == .company && g.company.payroll > 0', 'company payroll spread evenly over its employees (per-employee ceilings applied to the average wage)')], 'guards': ['c0.amount 50000 == 700', 'c0.amount 200000 == 2800', 'c1.amount 50000 == 7000', 'c1.amount 200000 == 28000', 'c2.amount 50000 == 1500', 'c2.amount 200000 == 6000', 'c3.amount 50000 == 400', 'c3.amount 200000 == 1600', 'c4.amount 50000 == 125', 'c4.amount 200000 == 500', 'c5.amount 50000 == 250', 'c5.amount 200000 == 1000', 'c6.amount 50000 == 250', 'c6.amount 200000 == 1000', 'c7.amount 50000 == 2375', 'c7.amount 200000 == 9500', 'c8.amount 50000 == 5000', 'c8.amount 200000 == 20000'], 'taxes': [{'oecd': '2200', 'tax': 'Nemocenské poistenie (zamestnávateľ)', 'statute': 'zákon 461/2003 Z. z. § 130 písm. b): 1,4 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Starobné poistenie (zamestnávateľ)', 'statute': 'zákon 461/2003 Z. z. § 131 ods. 1 písm. b): 14 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Invalidné poistenie (zamestnávateľ)', 'statute': 'zákon 461/2003 Z. z. § 132 písm. b): 3 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Úrazové poistenie', 'statute': 'zákon 461/2003 Z. z. § 133: 0,8 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Garančné poistenie', 'statute': 'zákon 461/2003 Z. z. § 135: 0,25 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Poistenie v nezamestnanosti (zamestnávateľ)', 'statute': 'zákon 461/2003 Z. z. § 136 písm. b) bod 1: 0,5 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Poistné na financovanie podpory', 'statute': 'zákon 461/2003 Z. z. § 136a: 0,5 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Rezervný fond solidarity (zamestnávateľ)', 'statute': 'zákon 461/2003 Z. z. § 137 písm. a): 4,75 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Zdravotné poistenie (zamestnávateľ)', 'statute': 'zákon 580/2004 Z. z. § 12 ods. 1 písm. d): 10 %', 'dated': 'Slov-Lex znenie účinné od 1.1.2025', 'grade': 'A', 'kernel_parts': ['Contribution'], 'unsupported': []}]}
